"""The committed image datasets, checked against the code that has to consume them.

Two things can only be caught here, because they span the two halves of the repository:

* `datasets/_gen/_lib.render_digest` and `atlas_bench.images.render_digest` are two
  implementations of one fingerprint. If they drift, a fidelity run silently refuses every
  case (or, worse, accepts a reference from another spec), and nothing else notices.
* The reference images the edit cases condition on are committed *and* regenerated by the
  generator. If a Pillow upgrade moves a pixel, the committed bytes and a fresh render stop
  matching, and edit results from before and after would be compared as if they had seen
  the same input.
"""

from __future__ import annotations

import importlib.util
import json
import sys
from pathlib import Path

import pytest

from atlas_bench.images import render_digest

REPO_ROOT = Path(__file__).resolve().parents[2]
DATASETS = REPO_ROOT / "datasets"
SUITES = ("eval-t2i-text-v1", "eval-t2i-adherence-v1", "eval-t2i-rgba-v1",
          "eval-t2i-fidelity-v1")


def rows_of(dataset_id: str) -> list[dict]:
    path = DATASETS / dataset_id / "items.jsonl"
    return [json.loads(line) for line in path.read_text(encoding="utf-8").splitlines() if line]


def load_generator():
    """Import `datasets/_gen/gen_t2i.py` the way the generators import each other."""
    gen_dir = DATASETS / "_gen"
    sys.path.insert(0, str(gen_dir))
    try:
        spec = importlib.util.spec_from_file_location("gen_t2i_test", gen_dir / "gen_t2i.py")
        module = importlib.util.module_from_spec(spec)
        sys.modules["gen_t2i_test"] = module
        spec.loader.exec_module(module)
        return module
    finally:
        sys.path.remove(str(gen_dir))


@pytest.mark.parametrize("dataset_id", SUITES)
def test_every_row_carries_a_render_spec_the_harness_can_execute(dataset_id: str) -> None:
    for row in rows_of(dataset_id):
        render = row["meta"]["render"]
        assert render["steps"] == 40
        assert render["width"] % 32 == 0 and render["height"] % 32 == 0
        assert isinstance(render["seed"], int)
        assert row["prompt"].strip()


@pytest.mark.parametrize("dataset_id", SUITES)
def test_the_two_render_digest_implementations_agree(dataset_id: str) -> None:
    """The dataset generator's digest and the harness's must be the same function."""
    for row in rows_of(dataset_id):
        assert row["meta"]["render_digest"] == render_digest(row["prompt"], row["meta"]["render"])


def test_the_fidelity_suite_pins_the_digest_in_its_answer() -> None:
    for row in rows_of("eval-t2i-fidelity-v1"):
        assert row["answer"]["reference"] == "bf16-same-box"
        assert row["answer"]["render_digest"] == row["meta"]["render_digest"]


def test_case_ids_are_shared_across_the_suites() -> None:
    """One case, one id, everywhere: a text score and a fidelity score must join."""
    fidelity = {row["id"]: row for row in rows_of("eval-t2i-fidelity-v1")}
    assert len(fidelity) == 24
    for dataset_id in ("eval-t2i-text-v1", "eval-t2i-adherence-v1", "eval-t2i-rgba-v1"):
        for row in rows_of(dataset_id):
            assert row["id"] in fidelity, f"{row['id']} is not in the fidelity suite"
            assert row["prompt"] == fidelity[row["id"]]["prompt"]
            assert row["meta"]["render"] == fidelity[row["id"]]["meta"]["render"]


@pytest.mark.parametrize("dataset_id", (*SUITES, "t2i-prompts-v1"))
def test_reference_images_exist_and_stay_small(dataset_id: str) -> None:
    directory = DATASETS / dataset_id
    for row in rows_of(dataset_id):
        names = row.get("reference_images") or row["meta"].get("reference_images") or []
        for name in names:
            path = directory / name
            assert path.is_file(), f"{row['id']} references missing {name}"
            assert path.stat().st_size <= 30 * 1024


def test_reference_images_regenerate_byte_for_byte(tmp_path: Path) -> None:
    generator = load_generator()
    for name, draw in generator.REFERENCES.items():
        fresh = tmp_path / name
        draw().save(fresh, format="PNG", optimize=True)
        committed = DATASETS / "eval-t2i-fidelity-v1" / "images" / name
        if not committed.is_file():
            committed = DATASETS / "t2i-prompts-v1" / "images" / name
        assert committed.read_bytes() == fresh.read_bytes(), (
            f"{name} no longer regenerates to the committed bytes — the edit cases would be "
            "conditioned on different pixels than the results already in the atlas"
        )


def test_the_case_table_and_the_committed_rows_are_the_same_set() -> None:
    generator = load_generator()
    assert [case.id for case in generator.CASES] == [row["id"] for row in
                                                     rows_of("eval-t2i-fidelity-v1")]
    assert len(generator.SPEED_PROMPTS) == len(rows_of("t2i-prompts-v1"))


def test_the_prompts_dataset_covers_every_latency_workload_category() -> None:
    categories = {row["category"] for row in rows_of("t2i-prompts-v1")}
    for workload_id in ("t2i-single-1k-40s-v1", "t2i-single-2k-40s-v1",
                        "edit-ref1-1k-40s-v1", "edit-ref4-1k-40s-v1"):
        workload = json.loads((REPO_ROOT / "workloads" / f"{workload_id}.json").read_text())
        params = workload["params"]
        wanted = set(params["dataset_categories"])
        assert wanted <= categories
        rows = [r for r in rows_of("t2i-prompts-v1") if r["category"] in wanted]
        assert len(rows) >= params["num_requests"], f"{workload_id} asks for more rows than exist"
        for row in rows[: params["num_requests"]]:
            assert len(row.get("reference_images") or []) == params["ref_images"]
